// Hard invariant: a nav path can only ever exist once per group. Earlier code only had a
// *comment* claiming this was protected — no code actually enforced it, which is exactly why
// "Backup & Restore" (and potentially any other item) could render twice in the sidebar if it
// ever ended up duplicated (stale cached bundle, merge artifact, future edit, etc.). This runs
// once at module load and actually removes any repeat before the sidebar ever renders.
NAV_GROUPS.forEach((group) => {
  const seenPaths = new Set();
  group.items = group.items.filter((item) => {
    if (seenPaths.has(item.path)) {
      if (typeof console !== 'undefined') console.warn(`[DashboardLayout] Duplicate nav item removed for path "${item.path}" in group "${group.id}". Check NAV_GROUPS for a repeated entry.`);
      return false;
    }
    seenPaths.add(item.path);
    return true;
  });
});
